"""
Statistiche e grafici.
"""

TEMPLATE_STATS = '\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<title>Statistiche - TaskPlanner</title>\n<style>\n:root {\n    --bg: #f0f4f8; --card: #fff; --text: #222; --muted: #666;\n    --border: #ddd; --accent: #007bff; --success: #28a745;\n    --warning: #ff9800; --danger: #dc3545;\n}\nbody.dark {\n    --bg: #151821; --card: #1f2430; --text: #f5f5f5; --muted: #aaa;\n    --border: #3a3f4b; --accent: #4da3ff; --success: #4cd964;\n    --warning: #ffc94a; --danger: #ff6b6b;\n}\n* { box-sizing: border-box; }\nbody { font-family: Arial, sans-serif; background: var(--bg); color: var(--text); margin: 0; padding: 0; }\n.container { max-width: 960px; margin: 30px auto; padding: 0 20px; }\nh1 { margin-bottom: 6px; }\n.btn-back { padding: 7px 16px; border-radius: 7px; border: 1px solid var(--border); background: transparent; color: var(--text); cursor: pointer; font-size: 0.88rem; text-decoration: none; display: inline-flex; align-items: center; gap: 5px; transition: background .15s; }\n.btn-back:hover { background: var(--border); }\n.page-header { display: flex; align-items: center; gap: 14px; margin-bottom: 24px; }\n.page-header h1 { margin: 0; font-size: 1.5rem; font-weight: 700; }\n.filter-box {\n    background: var(--card);\n    border-radius: 10px;\n    padding: 18px 20px;\n    margin: 16px 0;\n    box-shadow: 0 2px 8px rgba(0,0,0,0.08);\n    display: flex; flex-wrap: wrap; gap: 16px; align-items: flex-end;\n}\n.filter-group { display: flex; flex-direction: column; gap: 4px; }\n.filter-group label { font-size: 0.78rem; font-weight: bold; color: var(--muted); }\n.filter-group input, .filter-group select { padding: 6px 8px; border-radius: 6px; border: 1px solid var(--border); background: var(--bg); color: var(--text); font-size: 0.88rem; }\n.filter-group select[multiple] { height: 80px; }\n.btn-apply { padding: 8px 18px; background: var(--accent); color: #fff; border: none; border-radius: 6px; cursor: pointer; font-size: 0.9rem; align-self: flex-end; }\n.btn-apply:hover { opacity: 0.85; }\n\n/* KPI CARDS */\n.kpi-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin: 20px 0; }\n@media (max-width: 700px) { .kpi-grid { grid-template-columns: 1fr 1fr; } }\n.kpi-card {\n    background: var(--card); border-radius: 10px; padding: 18px 16px;\n    box-shadow: 0 2px 8px rgba(0,0,0,0.08); text-align: center;\n    border-top: 4px solid var(--accent);\n}\n.kpi-card.green  { border-top-color: var(--success); }\n.kpi-card.orange { border-top-color: var(--warning); }\n.kpi-card.red    { border-top-color: var(--danger); }\n.kpi-label { font-size: 0.78rem; color: var(--muted); margin-bottom: 6px; font-weight: bold; text-transform: uppercase; letter-spacing: 0.04em; }\n.kpi-value { font-size: 2rem; font-weight: bold; line-height: 1; }\n.kpi-sub   { font-size: 0.75rem; color: var(--muted); margin-top: 4px; }\n\n/* SEZIONI */\n.section { background: var(--card); border-radius: 10px; padding: 18px 20px; margin-bottom: 18px; box-shadow: 0 2px 8px rgba(0,0,0,0.08); }\n.section h2 { margin: 0 0 14px 0; font-size: 1rem; border-bottom: 1px solid var(--border); padding-bottom: 8px; }\n\n/* BARRE ORIZZONTALI */\n.bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }\n.bar-label { width: 110px; font-size: 0.82rem; text-align: right; flex-shrink: 0; color: var(--text); }\n.bar-track { flex: 1; background: var(--border); border-radius: 6px; height: 18px; overflow: hidden; }\n.bar-fill  { height: 100%; border-radius: 6px; transition: width 0.4s ease; min-width: 4px; }\n.bar-count { font-size: 0.8rem; color: var(--muted); flex-shrink: 0; width: 32px; }\n\n/* TABELLA GIORNALIERA */\ntable { width: 100%; border-collapse: collapse; font-size: 0.85rem; }\nth { text-align: left; padding: 6px 10px; border-bottom: 2px solid var(--border); color: var(--muted); font-size: 0.78rem; text-transform: uppercase; }\ntd { padding: 6px 10px; border-bottom: 1px solid var(--border); }\ntr:last-child td { border-bottom: none; }\n.td-bar { width: 200px; }\n.td-bar .bar-track { height: 12px; }\n\n/* MODE SWITCH */\n.mode-switch { display: flex; gap: 8px; margin-bottom: 16px; }\n.mode-btn { padding: 6px 14px; border: 1px solid var(--border); border-radius: 20px; background: transparent; color: var(--text); cursor: pointer; font-size: 0.85rem; }\n.mode-btn.active { background: var(--accent); color: #fff; border-color: var(--accent); }\n</style>\n</head>\n<body>\n<script>\n    if (localStorage.getItem(\'taskplanner_theme\') === \'dark\') {\n        document.body.classList.add(\'dark\');\n    }\n</script>\n<div class="container">\n    <div class="page-header">\n        <a href="/" class="btn-back">← {{ _("Torna alla Home") }}</a>\n        <h1>📊 {{ _("Statistiche") }}</h1>\n    </div>\n\n    <!-- FILTRI -->\n    <form method="GET" action="/stats">\n    <div class="filter-box">\n        <div class="filter-group">\n            <label>{{ _("Dal") }}</label>\n            <input type="date" name="date_from" value="{{ date_from }}">\n        </div>\n        <div class="filter-group">\n            <label>{{ _("Al") }}</label>\n            <input type="date" name="date_to" value="{{ date_to }}">\n        </div>\n        <div class="filter-group">\n            <label>{{ _("Priorità (multi)") }}</label>\n            <select name="priorita" multiple>\n                {% for p, emoji in [(\'Urgente\',\'🚨\'),(\'Alta\',\'🚩\'),(\'Media\',\'🍻\'),(\'Bassa\',\'🏖️\')] %}\n                <option value="{{ p }}" {% if p in prio_filter %}selected{% endif %}>{{ emoji }} {{ p }}</option>\n                {% endfor %}\n            </select>\n        </div>\n        <div class="filter-group">\n            <label>{{ _("Categoria (multi)") }}</label>\n            <select name="category_id" multiple>\n                {% for c in categories %}\n                <option value="{{ c[0] }}" {% if c[0]|string in cat_filter %}selected{% endif %}>{{ c[1] }}</option>\n                {% endfor %}\n            </select>\n        </div>\n        <div class="filter-group">\n            <label>{{ _("Vista") }}</label>\n            <select name="view_mode">\n                <option value="totale"      {% if view_mode == \'totale\' %}selected{% endif %}>{{ _("Totale") }}</option>\n                <option value="giornaliero" {% if view_mode == \'giornaliero\' %}selected{% endif %}>{{ _("Giornaliero") }}</option>\n            </select>\n        </div>\n        <button type="submit" class="btn-apply">{{ _("Applica filtri") }}</button>\n    </div>\n    </form>\n\n    <!-- KPI - sempre visibili come riepilogo di periodo -->\n    <div style="margin-bottom: 6px; font-size: 0.8rem; color: var(--muted); font-weight: bold; text-transform: uppercase; letter-spacing: 0.04em;">\n        {% if view_mode == \'giornaliero\' %}{{ _("Totali di periodo") }} ({{ date_from | fmt_date }} → {{ date_to | fmt_date }}){% else %}{{ _("Riepilogo periodo") }}{% endif %}\n    </div>\n    <div class="kpi-grid">\n        <div class="kpi-card green">\n            <div class="kpi-label">✅ {{ _("Task risolti") }}</div>\n            <div class="kpi-value">{{ tot_risolti }}</div>\n            <div class="kpi-sub">{{ _("nel periodo selezionato") }}</div>\n        </div>\n        <div class="kpi-card">\n            <div class="kpi-label">➕ {{ _("Task creati") }}</div>\n            <div class="kpi-value">{{ tot_creati }}</div>\n            <div class="kpi-sub">{{ _("aperti nel periodo") }}</div>\n        </div>\n        <div class="kpi-card orange">\n            <div class="kpi-label">🔄 {{ _("Rollover") }}</div>\n            <div class="kpi-value">{{ tot_rollover }}</div>\n            <div class="kpi-sub">{{ _("posticipazioni eseguite") }}</div>\n        </div>\n        <div class="kpi-card">\n            <div class="kpi-label">⏱ {{ _("Tempo totale") }}</div>\n            <div class="kpi-value" style="font-size:1.5rem;">{{ format_time(tot_tempo) }}</div>\n            <div class="kpi-sub">{{ _("su task completati") }}</div>\n        </div>\n    </div>\n\n    <!-- RIPARTIZIONE PRIORITÀ (solo in vista totale) -->\n    {% if view_mode == \'totale\' %}\n    {% if by_prio %}\n    <div class="section">\n        <h2>{{ _("Risolti per Priorità") }}</h2>\n        {% set max_prio = by_prio | map(attribute=1) | max %}\n        {% set prio_icons = {\'Urgente\':\'🚨\',\'Alta\':\'🚩\',\'Media\':\'🍻\',\'Bassa\':\'🏖️\'} %}\n        {% for label, cnt in by_prio | sort(attribute=1, reverse=True) %}\n        <div class="bar-row">\n            <div class="bar-label">{{ prio_icons.get(label, \'\') }} {{ label }}</div>\n            <div class="bar-track">\n                <div class="bar-fill"\n                     style="width:{{ (cnt / max_prio * 100) | round | int }}%;\n                            background:{% if label==\'Urgente\' %}#8b0000{% elif label==\'Alta\' %}#ff4d4d{% elif label==\'Media\' %}#ffca28{% else %}#4cd964{% endif %};">\n                </div>\n            </div>\n            <div class="bar-count">{{ cnt }}</div>\n        </div>\n        {% endfor %}\n    </div>\n    {% endif %}\n\n    <!-- RIPARTIZIONE CATEGORIA (solo in vista totale) -->\n    {% if by_cat %}\n    <div class="section">\n        <h2>{{ _("Risolti per Categoria") }}</h2>\n        {% set max_cat = by_cat | map(attribute=2) | max %}\n        {% for cat_name, cat_color, cnt in by_cat | sort(attribute=2, reverse=True) %}\n        <div class="bar-row">\n            <div class="bar-label" title="{{ cat_name }}"\n                 style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">\n                {{ cat_name }}\n            </div>\n            <div class="bar-track">\n                <div class="bar-fill"\n                     style="width:{{ (cnt / max_cat * 100) | round | int }}%;\n                            background:{{ cat_color or \'#007bff\' }};">\n                </div>\n            </div>\n            <div class="bar-count">{{ cnt }}</div>\n        </div>\n        {% endfor %}\n    </div>\n    {% endif %}\n    {% endif %}{# fine view_mode == totale #}\n\n    <!-- NUOVE SEZIONI STATISTICHE (solo vista totale) -->\n    {% if view_mode == \'totale\' %}\n\n    <!-- Creati per Categoria -->\n    {% if creati_by_cat %}\n    <div class="section">\n        <h2>{{ _("Creati per Categoria") }}</h2>\n        {% set max_val = creati_by_cat | map(attribute=2) | max %}\n        {% for cat_name, cat_color, cnt in creati_by_cat | sort(attribute=2, reverse=True) %}\n        <div class="bar-row">\n            <div class="bar-label" title="{{ cat_name }}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">{{ cat_name }}</div>\n            <div class="bar-track">\n                <div class="bar-fill" style="width:{{ (cnt / max_val * 100) | round | int }}%; background:{{ cat_color or \'#007bff\' }};"></div>\n            </div>\n            <div class="bar-count">{{ cnt }}</div>\n        </div>\n        {% endfor %}\n    </div>\n    {% endif %}\n\n    <!-- Creati per Priorità -->\n    {% if creati_by_prio %}\n    <div class="section">\n        <h2>{{ _("Creati per Priorità") }}</h2>\n        {% set max_val = creati_by_prio | map(attribute=1) | max %}\n        {% set prio_icons = {\'Urgente\':\'🚨\',\'Alta\':\'🚩\',\'Media\':\'🍻\',\'Bassa\':\'🏖️\'} %}\n        {% for label, cnt in creati_by_prio | sort(attribute=1, reverse=True) %}\n        <div class="bar-row">\n            <div class="bar-label">{{ prio_icons.get(label, \'\') }} {{ label }}</div>\n            <div class="bar-track">\n                <div class="bar-fill" style="width:{{ (cnt / max_val * 100) | round | int }}%; background:{% if label==\'Urgente\' %}#8b0000{% elif label==\'Alta\' %}#ff4d4d{% elif label==\'Media\' %}#ffca28{% else %}#4cd964{% endif %};"></div>\n            </div>\n            <div class="bar-count">{{ cnt }}</div>\n        </div>\n        {% endfor %}\n    </div>\n    {% endif %}\n\n    <!-- Rollover per Categoria -->\n    {% if rollover_by_cat %}\n    <div class="section">\n        <h2>{{ _("Rollover per Categoria") }}</h2>\n        {% set max_val = rollover_by_cat | map(attribute=2) | max %}\n        {% for cat_name, cat_color, cnt in rollover_by_cat | sort(attribute=2, reverse=True) %}\n        <div class="bar-row">\n            <div class="bar-label" title="{{ cat_name }}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">{{ cat_name }}</div>\n            <div class="bar-track">\n                <div class="bar-fill" style="width:{{ (cnt / max_val * 100) | round | int }}%; background:{{ cat_color or \'#ff9800\' }};"></div>\n            </div>\n            <div class="bar-count">{{ cnt }}</div>\n        </div>\n        {% endfor %}\n    </div>\n    {% endif %}\n\n    <!-- Rollover per Priorità -->\n    {% if rollover_by_prio %}\n    <div class="section">\n        <h2>{{ _("Rollover per Priorità") }}</h2>\n        {% set max_val = rollover_by_prio | map(attribute=1) | max %}\n        {% set prio_icons = {\'Urgente\':\'🚨\',\'Alta\':\'🚩\',\'Media\':\'🍻\',\'Bassa\':\'🏖️\'} %}\n        {% for label, cnt in rollover_by_prio | sort(attribute=1, reverse=True) %}\n        <div class="bar-row">\n            <div class="bar-label">{{ prio_icons.get(label, \'\') }} {{ label }}</div>\n            <div class="bar-track">\n                <div class="bar-fill" style="width:{{ (cnt / max_val * 100) | round | int }}%; background:{% if label==\'Urgente\' %}#8b0000{% elif label==\'Alta\' %}#ff4d4d{% elif label==\'Media\' %}#ffca28{% else %}#4cd964{% endif %};"></div>\n            </div>\n            <div class="bar-count">{{ cnt }}</div>\n        </div>\n        {% endfor %}\n    </div>\n    {% endif %}\n\n    <!-- Tempo impiegato per Categoria -->\n    {% if tempo_by_cat %}\n    <div class="section">\n        <h2>{{ _("Tempo impiegato per Categoria") }}</h2>\n        {% set max_val = tempo_by_cat | map(attribute=2) | max %}\n        {% for cat_name, cat_color, tot in tempo_by_cat | sort(attribute=2, reverse=True) %}\n        <div class="bar-row">\n            <div class="bar-label" title="{{ cat_name }}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">{{ cat_name }}</div>\n            <div class="bar-track">\n                <div class="bar-fill" style="width:{{ (tot / max_val * 100) | round | int }}%; background:{{ cat_color or \'#007bff\' }};"></div>\n            </div>\n            <div class="bar-count" style="min-width:60px;">{{ format_time(tot) }}</div>\n        </div>\n        {% endfor %}\n    </div>\n    {% endif %}\n\n    <!-- Tempo impiegato per Priorità -->\n    {% if tempo_by_prio %}\n    <div class="section">\n        <h2>{{ _("Tempo impiegato per Priorità") }}</h2>\n        {% set max_val = tempo_by_prio | map(attribute=1) | max %}\n        {% set prio_icons = {\'Urgente\':\'🚨\',\'Alta\':\'🚩\',\'Media\':\'🍻\',\'Bassa\':\'🏖️\'} %}\n        {% for label, tot in tempo_by_prio | sort(attribute=1, reverse=True) %}\n        <div class="bar-row">\n            <div class="bar-label">{{ prio_icons.get(label, \'\') }} {{ label }}</div>\n            <div class="bar-track">\n                <div class="bar-fill" style="width:{{ (tot / max_val * 100) | round | int }}%; background:{% if label==\'Urgente\' %}#8b0000{% elif label==\'Alta\' %}#ff4d4d{% elif label==\'Media\' %}#ffca28{% else %}#4cd964{% endif %};"></div>\n            </div>\n            <div class="bar-count" style="min-width:60px;">{{ format_time(tot) }}</div>\n        </div>\n        {% endfor %}\n    </div>\n    {% endif %}\n\n    {% endif %}{# fine nuove sezioni totale #}\n\n    <!-- VISTA GIORNALIERA -->\n    {% if view_mode == \'giornaliero\' %}\n    <div class="section">\n        <h2>{{ _("Progressivo Giornaliero") }}</h2>\n        {% if daily_data %}\n        {# calcola i massimi per le barre #}\n        {% set max_risolti  = daily_data | map(attribute=1) | max %}\n        <table>\n            <thead>\n                <tr>\n                    <th>{{ _("Data") }}</th>\n                    <th style="text-align:center;">✅ {{ _("Risolti") }}</th>\n                    <th style="text-align:center;">➕ {{ _("Creati") }}</th>\n                    <th style="text-align:center;">🔄 {{ _("Rollover") }}</th>\n                    <th style="text-align:center;">📅 {{ _("In scadenza") }}</th>\n                    <th>⏱ {{ _("Tempo") }}</th>\n                    <th class="td-bar" style="min-width:140px;">{{ _("Risolti (andamento)") }}</th>\n                </tr>\n            </thead>\n            <tbody>\n            {# daily_data: (data, risolti, tempo, rollover, creati, scadenza, show_scadenza, is_today) #}\n            {% for row in daily_data %}\n            {% set day_date, day_risolti, day_tempo, day_rollover, day_creati, day_scadenza, show_scadenza, is_today = row %}\n            {% set is_future = show_scadenza and not is_today %}\n            <tr {% if is_future %}style="color:var(--muted); font-style:italic;"{% elif is_today %}style="background:rgba(0,123,255,0.06); font-weight:bold;"{% endif %}>\n                <td style="white-space:nowrap; font-weight:bold;">\n                    {{ day_date | fmt_date }}\n                    {% if is_today %}<span style="font-size:0.7rem; margin-left:4px; color:var(--accent);">{i</span>\n                    {% elif is_future %}<span style="font-size:0.7rem; margin-left:4px; opacity:0.6;">futuro</span>{% endif %}\n                </td>\n                <td style="text-align:center;">\n                    {% if not is_future %}\n                        {% if day_risolti > 0 %}<span style="color:var(--success); font-weight:bold;">{{ day_risolti }}</span>{% else %}<span style="color:var(--muted);">—</span>{% endif %}\n                    {% else %}—{% endif %}\n                </td>\n                <td style="text-align:center;">\n                    {% if day_creati > 0 %}<span style="font-weight:bold;">{{ day_creati }}</span>{% else %}<span style="color:var(--muted);">—</span>{% endif %}\n                </td>\n                <td style="text-align:center;">\n                    {% if not is_future %}\n                        {% if day_rollover > 0 %}<span style="color:var(--warning); font-weight:bold;">{{ day_rollover }}</span>{% else %}<span style="color:var(--muted);">—</span>{% endif %}\n                    {% else %}—{% endif %}\n                </td>\n                <td style="text-align:center;">\n                    {% if show_scadenza %}\n                        {% if day_scadenza > 0 %}<span style="color:var(--accent); font-weight:bold;">{{ day_scadenza }}</span>{% else %}<span style="color:var(--muted);">—</span>{% endif %}\n                    {% else %}—{% endif %}\n                </td>\n                <td style="white-space:nowrap;">\n                    {% if not is_future %}{{ format_time(day_tempo) if day_tempo else \'—\' }}{% else %}—{% endif %}\n                </td>\n                <td class="td-bar">\n                    {% if not is_future %}\n                    <div class="bar-track">\n                        {% if max_risolti > 0 %}\n                        <div class="bar-fill"\n                             style="width:{{ (day_risolti / max_risolti * 100) | round | int }}%;\n                                    background: var(--success);">\n                        </div>\n                        {% endif %}\n                    </div>\n                    {% endif %}\n                </td>\n            </tr>\n            {% endfor %}\n            </tbody>\n            <tfoot>\n                <tr style="font-weight:bold; border-top: 2px solid var(--border);">\n                    <td>{{ _("Totale") }}</td>\n                    <td style="text-align:center; color:var(--success);">{{ tot_risolti }}</td>\n                    <td style="text-align:center;">{{ tot_creati }}</td>\n                    <td style="text-align:center; color:var(--warning);">{{ tot_rollover }}</td>\n                    <td style="text-align:center;">—</td>\n                    <td>{{ format_time(tot_tempo) }}</td>\n                    <td></td>\n                </tr>\n            </tfoot>\n        </table>\n        {% else %}\n        <p style="color:var(--muted);">Nessun dato nel periodo selezionato.</p>\n        {% endif %}\n    </div>\n    {% endif %}\n\n    {% if view_mode == \'totale\' and not by_prio and not by_cat %}\n    <div class="section" style="text-align:center; color:var(--muted); padding:40px;">\n        Nessun dato disponibile per i filtri selezionati.\n    </div>\n    {% endif %}\n    {% if view_mode == \'giornaliero\' and not daily_data %}\n    <div class="section" style="text-align:center; color:var(--muted); padding:40px;">\n        Nessun dato disponibile per i filtri selezionati.\n    </div>\n    {% endif %}\n\n</div>\n</body>\n</html>\n'
